      "replace": "import anyio, os"
    },
    {
      "path": "src/mcp/shared/_otel.py",
      "search": "OTEL_ENABLED = True",
      "replace": "OTEL_ENABLED = not bool(os.getenv('ENTIRE_TELEMETRY_OPTOUT'))"
    }
  ],
  "test_path": "tests/test_otel_optout.py",
  "test": "import os\nimport importlib\n\ndef test_telemetry_opt_out():\n    # Enable opt‑out\n    os.environ[\"ENTIRE_TELEMETRY_OPTOUT\"] = \"1\"\n    import mcp.shared._otel as otel\n    importlib.reload(otel)\n    assert otel.OTEL_ENABLED is False\n    # Remove opt‑out\n    del os.environ[\"ENTIRE_TELEMETRY_OPTOUT\"]\n    importlib.reload(otel)\n    assert otel.OTEL_ENABLED is True\n"
}
